importScripts("https://cdn.jsdelivr.net/pyodide/v0.25.0/full/pyodide.js");

function sendPatch(patch, buffers, msg_id) {
  self.postMessage({
    type: 'patch',
    patch: patch,
    buffers: buffers
  })
}

async function startApplication() {
  console.log("Loading pyodide!");
  self.postMessage({type: 'status', msg: 'Loading pyodide'})
  self.pyodide = await loadPyodide();
  self.pyodide.globals.set("sendPatch", sendPatch);
  console.log("Loaded!");
  await self.pyodide.loadPackage("micropip");
  const env_spec = ['https://tigi-prof-tigi.github.io/tgmaster-afe-python/apps/_vendor/wheels/bokeh-3.4.3-py3-none-any.whl', 'https://tigi-prof-tigi.github.io/tgmaster-afe-python/apps/_vendor/wheels/panel-1.4.5-py3-none-any.whl', 'pyodide-http==0.2.1', 'contextlib', 'html', 'io', 'math', 'pathlib', 'statistics']
  for (const pkg of env_spec) {
    let pkg_name;
    if (pkg.endsWith('.whl')) {
      pkg_name = pkg.split('/').slice(-1)[0].split('-')[0]
    } else {
      pkg_name = pkg
    }
    self.postMessage({type: 'status', msg: `Installing ${pkg_name}`})
    try {
      await self.pyodide.runPythonAsync(`
        import micropip
        await micropip.install('${pkg}');
      `);
    } catch(e) {
      console.log(e)
      self.postMessage({
	type: 'status',
	msg: `Error while installing ${pkg_name}`
      });
    }
  }
  console.log("Packages loaded!");
  self.postMessage({type: 'status', msg: 'Executing code'})
  const code = `
  \nimport asyncio\n\nfrom panel.io.pyodide import init_doc, write_doc\n\ninit_doc()\n\n# === FICHIER GENERE \u2014 ne pas editer (voir exercices.py et app.py) ===\n# -*- coding: utf-8 -*-\n"""Banque d'exercices Python \u2014 Initiation au metier de charge d'affaire / analyse credit bancaire (B3-AFE n\xb015).\n\nTgMaster University (prononcer "Tiji Master University").\n\nChaque exercice est un dictionnaire :\n  id        : identifiant court unique\n  seance    : numero de seance source (alignement avec les .md et les TPs Excel)\n  titre     : libelle affiche dans le menu deroulant\n  consigne  : enonce en Markdown (donnees + travail demande)\n  starter   : code de depart pre-rempli dans l'editeur (avec les donnees deja saisies)\n  solution  : solution de reference. Le moteur l'execute UNE fois au demarrage pour\n              en deduire les valeurs attendues des variables verifiees. On ne code donc\n              jamais "en dur" un resultat : la verite vient du calcul lui-meme.\n  verifs    : liste de controles (variable a produire, tolerance absolue, unite).\n\nLes donnees reprennent le contexte SYSCOHADA / BCEAO des 4 TPs Excel du cours :\n  TP1 solvabilite et structure (FRNG, BFR, tresorerie nette, autonomie, gearing)\n  TP2 liquidite, CAF additive, capacite de remboursement (DSCR)\n  TP3 scoring Altman Z'' (marches emergents) + zone de risque\n  TP4 montage et tarification d'un credit (annuite constante, amortissement, TEG)\nEntreprises fictives : AGRO-CI SARL, BTP Kouassi & Associes, Industrie Bamba SA,\nDistribution Traore SA. Montants en FCFA, IS 25 %, normes prudentielles BCEAO.\n"""\n\nEXERCICES = [\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s02_frng_bfr_tn",\n        "seance": 2,\n        "titre": "S2 \xb7 Equilibre fonctionnel \u2014 FRNG, BFR, tresorerie nette",\n        "consigne": """\n### Equilibre du bilan fonctionnel d'AGRO-CI SARL (exercice N)\n\nVous etes charge d'affaires PME a la BNI. Avant d'engager un credit, vous analysez\nl'equilibre fonctionnel du bilan SYSCOHADA d'AGRO-CI SARL.\n\n| Poste (FCFA) | Montant |\n|--------------|---------|\n| Emplois stables (actif immobilise) | 700 000 000 |\n| Stocks | 230 000 000 |\n| Creances | 200 000 000 |\n| Capitaux propres | 430 000 000 |\n| Dettes financieres (>1 an) | 420 000 000 |\n| Dettes circulantes | 250 000 000 |\n\n**Travail demande :**\n1. Calculer les **ressources stables** puis le **FRNG** \u2192 \`ressources_stables\`, \`frng\`\n2. Calculer le **BFR** \u2192 \`bfr\`\n3. En deduire la **tresorerie nette** \u2192 \`tn\`\n\nRappels : Ressources stables = CP + Dettes fin. ; FRNG = Ressources stables - Emplois stables ;\nBFR = (Stocks + Creances) - Dettes circulantes ; Tresorerie nette = FRNG - BFR\n""",\n        "starter": """emplois_stables = 700_000_000\nstocks = 230_000_000\ncreances = 200_000_000\ncapitaux_propres = 430_000_000\ndettes_fin = 420_000_000\ndettes_circ = 250_000_000\n\n# 1) Ressources stables et FRNG\nressources_stables = ...\nfrng = ...\n\n# 2) Besoin en fonds de roulement\nbfr = ...\n\n# 3) Tresorerie nette\ntn = ...\n\nprint("FRNG =", frng, "FCFA")\nprint("BFR  =", bfr, "FCFA")\nprint("TN   =", tn, "FCFA")\n""",\n        "solution": """\nemplois_stables = 700_000_000\nstocks = 230_000_000\ncreances = 200_000_000\ncapitaux_propres = 430_000_000\ndettes_fin = 420_000_000\ndettes_circ = 250_000_000\nressources_stables = capitaux_propres + dettes_fin\nfrng = ressources_stables - emplois_stables\nbfr = (stocks + creances) - dettes_circ\ntn = frng - bfr\n""",\n        "verifs": [\n            {"var": "frng", "tol": 1_000_000, "unite": "FCFA"},\n            {"var": "bfr", "tol": 1_000_000, "unite": "FCFA"},\n            {"var": "tn", "tol": 1_000_000, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s03_ratios_structure",\n        "seance": 3,\n        "titre": "S3 \xb7 Ratios de structure et capacite d'endettement",\n        "consigne": """\n### Solidite financiere : autonomie, gearing, capacite d'endettement\n\nOn evalue la structure financiere d'AGRO-CI SARL (exercice N).\n\n| Element (FCFA) | Montant |\n|----------------|---------|\n| Capitaux propres | 430 000 000 |\n| Dettes financieres | 420 000 000 |\n| CAF annuelle | 120 000 000 |\n\n**Travail demande :**\n1. Calculer l'**autonomie financiere** \u2192 \`autonomie\`  (norme > 33 %)\n2. Calculer le **gearing** (ratio d'endettement) \u2192 \`gearing\`  (norme < 1,0)\n3. Calculer la **capacite d'endettement** \u2192 \`capacite_endettement\`  (norme bancaire < 4 ans)\n\nRappels : Autonomie = CP / (CP + Dettes fin.) ; Gearing = Dettes fin. / CP ;\nCapacite d'endettement = Dettes fin. / CAF\n""",\n        "starter": """capitaux_propres = 430_000_000\ndettes_fin = 420_000_000\ncaf = 120_000_000\n\n# 1) Autonomie financiere\nautonomie = ...\n\n# 2) Gearing (endettement)\ngearing = ...\n\n# 3) Capacite d'endettement (en annees de CAF)\ncapacite_endettement = ...\n\nprint("autonomie =", round(autonomie * 100, 1), "%")\nprint("gearing   =", round(gearing, 2))\nprint("capacite  =", round(capacite_endettement, 2), "ans")\n""",\n        "solution": """\ncapitaux_propres = 430_000_000\ndettes_fin = 420_000_000\ncaf = 120_000_000\nautonomie = capitaux_propres / (capitaux_propres + dettes_fin)\ngearing = dettes_fin / capitaux_propres\ncapacite_endettement = dettes_fin / caf\n""",\n        "verifs": [\n            {"var": "autonomie", "tol": 0.001, "unite": ""},\n            {"var": "gearing", "tol": 0.001, "unite": ""},\n            {"var": "capacite_endettement", "tol": 0.01, "unite": "ans"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s05_caf_additive",\n        "seance": 5,\n        "titre": "S5 \xb7 CAF par la methode additive (depuis l'EBE)",\n        "consigne": """\n### Capacite d'autofinancement de BTP Kouassi & Associes\n\nLa CAF mesure le flux de tresorerie potentiel de l'activite \u2014 la matiere premiere du\nremboursement. On la reconstitue par la **methode additive** a partir de l'EBE.\n\n| Element (FCFA) | Montant |\n|----------------|---------|\n| Excedent Brut d'Exploitation (EBE) | 180 000 000 |\n| Autres produits encaissables | 5 000 000 |\n| Autres charges decaissables | 8 000 000 |\n| Charges financieres (interets) | 22 000 000 |\n\n**Travail demande :** calculer la **CAF** \u2192 \`caf\`\n\nRappel : CAF = EBE + Autres produits encaissables - Autres charges decaissables - Charges financieres\n""",\n        "starter": """ebe = 180_000_000\nautres_produits = 5_000_000\nautres_charges = 8_000_000\ncharges_fin = 22_000_000\n\n# CAF par la methode additive\ncaf = ...\n\nprint("CAF =", caf, "FCFA")\n""",\n        "solution": """\nebe = 180_000_000\nautres_produits = 5_000_000\nautres_charges = 8_000_000\ncharges_fin = 22_000_000\ncaf = ebe + autres_produits - autres_charges - charges_fin\n""",\n        "verifs": [\n            {"var": "caf", "tol": 500_000, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s06_liquidite",\n        "seance": 6,\n        "titre": "S6 \xb7 Les trois ratios de liquidite",\n        "consigne": """\n### Liquidite a court terme de BTP Kouassi & Associes\n\nOn mesure la capacite a honorer le passif court avec l'actif court.\n\n| Element (FCFA) | Montant |\n|----------------|---------|\n| Stocks | 160 000 000 |\n| Creances clients + autres | 210 000 000 |\n| Tresorerie-actif | 35 000 000 |\n| Dettes circulantes | 240 000 000 |\n| Tresorerie-passif (concours bancaires) | 55 000 000 |\n\n**Travail demande :**\n1. Calculer le **passif court** (denominateur commun) \u2192 \`passif_court\`\n2. Calculer les trois ratios \u2192 \`generale\`, \`reduite\`, \`immediate\`\n\nRappels : Passif court = Dettes circ. + Treso-passif ;\nGenerale = (Stocks + Creances + Treso-actif) / Passif court ;\nReduite = (Creances + Treso-actif) / Passif court ; Immediate = Treso-actif / Passif court\n""",\n        "starter": """stocks = 160_000_000\ncreances = 210_000_000\ntreso_actif = 35_000_000\ndettes_circ = 240_000_000\ntreso_passif = 55_000_000\n\n# Passif court (denominateur commun)\npassif_court = ...\n\n# Les trois ratios de liquidite\ngenerale = ...\nreduite = ...\nimmediate = ...\n\nprint("generale  =", round(generale, 2))\nprint("reduite   =", round(reduite, 2))\nprint("immediate =", round(immediate, 2))\n""",\n        "solution": """\nstocks = 160_000_000\ncreances = 210_000_000\ntreso_actif = 35_000_000\ndettes_circ = 240_000_000\ntreso_passif = 55_000_000\npassif_court = dettes_circ + treso_passif\ngenerale = (stocks + creances + treso_actif) / passif_court\nreduite = (creances + treso_actif) / passif_court\nimmediate = treso_actif / passif_court\n""",\n        "verifs": [\n            {"var": "generale", "tol": 0.01, "unite": ""},\n            {"var": "reduite", "tol": 0.01, "unite": ""},\n            {"var": "immediate", "tol": 0.01, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s07_dscr",\n        "seance": 7,\n        "titre": "S7 \xb7 Capacite de remboursement \u2014 DSCR et Dettes/CAF",\n        "consigne": """\n### Les deux ratios bancaires de capacite de remboursement\n\nAvant l'octroi d'un credit, le banquier verifie que la CAF couvre le service de la dette.\n\n| Element (FCFA) | Montant |\n|----------------|---------|\n| CAF annuelle | 155 000 000 |\n| Annuite de remboursement (capital + interets) | 95 000 000 |\n| Dettes financieres (encours total) | 410 000 000 |\n\n**Travail demande :**\n1. Calculer le **DSCR** \u2192 \`dscr\`  (seuil banquier >= 1,25)\n2. Calculer le ratio **Dettes financieres / CAF** \u2192 \`dettes_caf\`  (seuil <= 4 ans)\n\nRappels : DSCR = CAF / Annuite ; Dettes/CAF = Dettes financieres / CAF\n""",\n        "starter": """caf = 155_000_000\nannuite = 95_000_000\ndettes_fin = 410_000_000\n\n# 1) DSCR (couverture du service de la dette)\ndscr = ...\n\n# 2) Dettes financieres / CAF (en annees)\ndettes_caf = ...\n\nprint("DSCR       =", round(dscr, 2))\nprint("Dettes/CAF =", round(dettes_caf, 2), "ans")\n""",\n        "solution": """\ncaf = 155_000_000\nannuite = 95_000_000\ndettes_fin = 410_000_000\ndscr = caf / annuite\ndettes_caf = dettes_fin / caf\n""",\n        "verifs": [\n            {"var": "dscr", "tol": 0.01, "unite": ""},\n            {"var": "dettes_caf", "tol": 0.01, "unite": "ans"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s08_altman_z",\n        "seance": 8,\n        "titre": "S8 \xb7 Scoring Altman Z'' \u2014 les 4 ratios et le score",\n        "consigne": """\n### Score de defaillance d'Industrie Bamba SA (modele Altman Z'')\n\nLe Z'' d'Altman (1995/2000) est concu pour les entreprises non cotees et les marches\nemergents. Il combine 4 ratios financiers ponderes.\n\n| Poste du bilan (FCFA) | Montant |\n|-----------------------|---------|\n| Total actif | 1 100 000 000 |\n| Actif circulant | 380 000 000 |\n| Passif circulant | 300 000 000 |\n| Reserves | 130 000 000 |\n| Resultat d'exploitation (EBIT) | 115 000 000 |\n| Total dettes | 680 000 000 |\n| Capitaux propres | 420 000 000 |\n\n**Travail demande :**\n1. Calculer les 4 ratios \u2192 \`x1\`, \`x2\`, \`x3\`, \`x4\`\n2. Calculer le score \u2192 \`z\`\n\nRappels : X1 = (AC - PC) / Total actif ; X2 = Reserves / Total actif ;\nX3 = EBIT / Total actif ; X4 = CP / Total dettes ;\nZ'' = 6,56\xb7X1 + 3,26\xb7X2 + 6,72\xb7X3 + 1,05\xb7X4\n""",\n        "starter": """total_actif = 1_100_000_000\nactif_circ = 380_000_000\npassif_circ = 300_000_000\nreserves = 130_000_000\nebit = 115_000_000\ntotal_dettes = 680_000_000\ncapitaux_propres = 420_000_000\n\n# 1) Les 4 ratios\nx1 = ...\nx2 = ...\nx3 = ...\nx4 = ...\n\n# 2) Score Z'' (somme ponderee)\nz = ...\n\nprint("X1..X4 =", round(x1, 4), round(x2, 4), round(x3, 4), round(x4, 4))\nprint("Z''    =", round(z, 2))\n""",\n        "solution": """\ntotal_actif = 1_100_000_000\nactif_circ = 380_000_000\npassif_circ = 300_000_000\nreserves = 130_000_000\nebit = 115_000_000\ntotal_dettes = 680_000_000\ncapitaux_propres = 420_000_000\nx1 = (actif_circ - passif_circ) / total_actif\nx2 = reserves / total_actif\nx3 = ebit / total_actif\nx4 = capitaux_propres / total_dettes\nz = 6.56 * x1 + 3.26 * x2 + 6.72 * x3 + 1.05 * x4\n""",\n        "verifs": [\n            {"var": "x1", "tol": 0.0005, "unite": ""},\n            {"var": "x4", "tol": 0.0005, "unite": ""},\n            {"var": "z", "tol": 0.02, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s09_annuite",\n        "seance": 9,\n        "titre": "S9 \xb7 Plan de financement et annuite constante",\n        "consigne": """\n### Montage du credit de Distribution Traore SA\n\nL'entreprise investit (entrepot + materiel). La banque ne finance que le besoin residuel\napres apport et subvention, par un credit amortissable a annuites constantes.\n\n| Parametre | Valeur |\n|-----------|--------|\n| Cout total de l'investissement | 300 000 000 FCFA |\n| Apport en fonds propres | 90 000 000 FCFA |\n| Subvention d'equipement | 10 000 000 FCFA |\n| Taux d'interet nominal | 9,5 % |\n| Duree du credit | 5 ans |\n\n**Travail demande :**\n1. Calculer le **montant emprunte** \u2192 \`emprunt\`\n2. Calculer l'**annuite constante** \u2192 \`annuite\`\n\nRappels : Emprunt = Cout - Apport - Subvention ;\nAnnuite = Emprunt \xd7 i / (1 - (1 + i)^(-n))\n""",\n        "starter": """cout = 300_000_000\napport = 90_000_000\nsubvention = 10_000_000\ni = 0.095\nn = 5\n\n# 1) Montant emprunte\nemprunt = ...\n\n# 2) Annuite constante\nannuite = ...\n\nprint("emprunt =", emprunt, "FCFA")\nprint("annuite =", round(annuite), "FCFA/an")\n""",\n        "solution": """\ncout = 300_000_000\napport = 90_000_000\nsubvention = 10_000_000\ni = 0.095\nn = 5\nemprunt = cout - apport - subvention\nannuite = emprunt * i / (1 - (1 + i) ** -n)\n""",\n        "verifs": [\n            {"var": "emprunt", "tol": 1_000_000, "unite": "FCFA"},\n            {"var": "annuite", "tol": 50_000, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s10_amortissement_an1",\n        "seance": 10,\n        "titre": "S10 \xb7 Tableau d'amortissement \u2014 premiere annee",\n        "consigne": """\n### Premiere ligne du tableau d'amortissement (annuites constantes)\n\nOn reprend le credit de Distribution Traore SA : montant emprunte **200 000 000 FCFA**,\ntaux **9,5 %**, duree 5 ans. L'annuite constante (deja calculee) est fournie.\n\n**Travail demande :** pour la **premiere annee** :\n1. Calculer les **interets** \u2192 \`interets1\`\n2. En deduire l'**amortissement du capital** \u2192 \`amort1\`\n3. Calculer le **capital restant du en fin d'annee 1** \u2192 \`capital_fin1\`\n\nRappels : Interets = Capital debut \xd7 i ; Amortissement = Annuite - Interets ;\nCapital fin = Capital debut - Amortissement\n""",\n        "starter": """emprunt = 200_000_000\ni = 0.095\nn = 5\nannuite = emprunt * i / (1 - (1 + i) ** -n)   # annuite constante (fournie)\n\n# 1) Interets de l'annee 1\ninterets1 = ...\n\n# 2) Amortissement du capital (annee 1)\namort1 = ...\n\n# 3) Capital restant du fin d'annee 1\ncapital_fin1 = ...\n\nprint("interets1    =", round(interets1))\nprint("amort1       =", round(amort1))\nprint("capital_fin1 =", round(capital_fin1))\n""",\n        "solution": """\nemprunt = 200_000_000\ni = 0.095\nn = 5\nannuite = emprunt * i / (1 - (1 + i) ** -n)\ninterets1 = emprunt * i\namort1 = annuite - interets1\ncapital_fin1 = emprunt - amort1\n""",\n        "verifs": [\n            {"var": "interets1", "tol": 500_000, "unite": "FCFA"},\n            {"var": "amort1", "tol": 100_000, "unite": "FCFA"},\n            {"var": "capital_fin1", "tol": 100_000, "unite": "FCFA"},\n        ],\n    },\n\n    # ================================================================== #\n    #  TIER AVANCE \u2014 exercices multi-etapes (boucles, listes, decision). #\n    #  Niveau MBA / \u2605\u2605\u2605.                                                #\n    # ================================================================== #\n    {\n        "id": "adv_effet_ciseaux",\n        "seance": 2,\n        "niveau": "avance",\n        "titre": "A1 \xb7 Effet de ciseau \u2014 tresorerie nette sur 2 exercices",\n        "consigne": """\n### Diagnostic de l'evolution : l'effet de ciseau FRNG / BFR\n\nOn dispose du bilan fonctionnel d'AGRO-CI SARL sur **deux exercices** (FCFA). On veut voir\nsi la tresorerie nette se degrade et pourquoi.\n\n| Poste | N-1 | N |\n|-------|-----|---|\n| Emplois stables | 620 M | 700 M |\n| Stocks | 180 M | 230 M |\n| Creances | 150 M | 200 M |\n| Capitaux propres | 400 M | 430 M |\n| Dettes financieres | 350 M | 420 M |\n| Dettes circulantes | 200 M | 250 M |\n\n**Travail demande :** pour CHAQUE exercice de la liste, calculer la tresorerie nette\n(\`tn = FRNG - BFR\`) et la stocker. Puis :\n1. la TN de l'exercice N-1 \u2192 \`tn_n1\`\n2. la TN de l'exercice N \u2192 \`tn_n\`\n3. la **variation du BFR** entre N-1 et N \u2192 \`var_bfr\`\n\nRappels : FRNG = (CP + Dettes fin.) - Emplois stables ; BFR = (Stocks + Creances) - Dettes circ.\n""",\n        "starter": """exercices = [\n    {"nom": "N-1", "emplois": 620, "stocks": 180, "creances": 150,\n     "cp": 400, "dettes_fin": 350, "dettes_circ": 200},\n    {"nom": "N",   "emplois": 700, "stocks": 230, "creances": 200,\n     "cp": 430, "dettes_fin": 420, "dettes_circ": 250},\n]\n\ntn = []        # tresorerie nette de chaque exercice\nbfr = []       # BFR de chaque exercice\nfor e in exercices:\n    frng = (e["cp"] + e["dettes_fin"]) - e["emplois"]\n    b = ...                       # BFR de l'exercice\n    bfr.append(b)\n    tn.append(frng - b)\n\ntn_n1 = tn[0]\ntn_n = tn[1]\nvar_bfr = ...                     # BFR(N) - BFR(N-1)\n\nprint("TN N-1 =", tn_n1, "M FCFA")\nprint("TN N   =", tn_n, "M FCFA")\nprint("var BFR =", var_bfr, "M FCFA")\n""",\n        "solution": """\nexercices = [\n    {"nom": "N-1", "emplois": 620, "stocks": 180, "creances": 150,\n     "cp": 400, "dettes_fin": 350, "dettes_circ": 200},\n    {"nom": "N",   "emplois": 700, "stocks": 230, "creances": 200,\n     "cp": 430, "dettes_fin": 420, "dettes_circ": 250},\n]\ntn = []\nbfr = []\nfor e in exercices:\n    frng = (e["cp"] + e["dettes_fin"]) - e["emplois"]\n    b = (e["stocks"] + e["creances"]) - e["dettes_circ"]\n    bfr.append(b)\n    tn.append(frng - b)\ntn_n1 = tn[0]\ntn_n = tn[1]\nvar_bfr = bfr[1] - bfr[0]\n""",\n        "verifs": [\n            {"var": "tn_n1", "tol": 0.5, "unite": "M FCFA"},\n            {"var": "tn_n", "tol": 0.5, "unite": "M FCFA"},\n            {"var": "var_bfr", "tol": 0.5, "unite": "M FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_altman_zone",\n        "seance": 8,\n        "niveau": "avance",\n        "titre": "A2 \xb7 Altman Z'' \u2014 zone de risque et probabilite de defaut",\n        "consigne": """\n### Du score a la decision : zone de risque et PD\n\nOn reprend Industrie Bamba SA (memes donnees que l'exercice de base S8). Apres le score Z'',\non doit le **traduire** en zone de risque puis en probabilite de defaut (PD).\n\nBornes : **Z'' > 2,60** = SAINE (code 2) | **1,10 \u2264 Z'' \u2264 2,60** = GRISE (code 1) |\n**Z'' < 1,10** = DETRESSE (code 0).\nPD indicative : SAINE 2 % | GRISE 12 % | DETRESSE 35 %.\n\n**Travail demande :**\n1. Calculer le score \u2192 \`z\`\n2. En deduire le **code de zone** (2 / 1 / 0) avec un \`if / elif / else\` \u2192 \`zone_code\`\n3. En deduire la **PD indicative** \u2192 \`pd\`\n""",\n        "starter": """total_actif = 1_100_000_000\nactif_circ = 380_000_000\npassif_circ = 300_000_000\nreserves = 130_000_000\nebit = 115_000_000\ntotal_dettes = 680_000_000\ncapitaux_propres = 420_000_000\n\nx1 = (actif_circ - passif_circ) / total_actif\nx2 = reserves / total_actif\nx3 = ebit / total_actif\nx4 = capitaux_propres / total_dettes\nz = 6.56 * x1 + 3.26 * x2 + 6.72 * x3 + 1.05 * x4\n\n# Determiner la zone (2 = saine, 1 = grise, 0 = detresse) et la PD\nif z > 2.60:\n    zone_code = 2\n    pd = 0.02\nelif z >= 1.10:\n    zone_code = ...\n    pd = ...\nelse:\n    zone_code = 0\n    pd = 0.35\n\nprint("Z''       =", round(z, 2))\nprint("zone_code =", zone_code)\nprint("PD        =", round(pd * 100, 1), "%")\n""",\n        "solution": """\ntotal_actif = 1_100_000_000\nactif_circ = 380_000_000\npassif_circ = 300_000_000\nreserves = 130_000_000\nebit = 115_000_000\ntotal_dettes = 680_000_000\ncapitaux_propres = 420_000_000\nx1 = (actif_circ - passif_circ) / total_actif\nx2 = reserves / total_actif\nx3 = ebit / total_actif\nx4 = capitaux_propres / total_dettes\nz = 6.56 * x1 + 3.26 * x2 + 6.72 * x3 + 1.05 * x4\nif z > 2.60:\n    zone_code = 2\n    pd = 0.02\nelif z >= 1.10:\n    zone_code = 1\n    pd = 0.12\nelse:\n    zone_code = 0\n    pd = 0.35\n""",\n        "verifs": [\n            {"var": "z", "tol": 0.02, "unite": ""},\n            {"var": "zone_code", "tol": 0.5, "unite": ""},\n            {"var": "pd", "tol": 0.005, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_tableau_amortissement",\n        "seance": 10,\n        "niveau": "avance",\n        "titre": "A3 \xb7 Tableau d'amortissement complet (boucle 5 ans)",\n        "consigne": """\n### Derouler tout le tableau d'amortissement\n\nCredit de **200 000 000 FCFA**, taux **9,5 %**, **5 ans**, annuites constantes. On deroule\nle tableau annee par annee dans une boucle, et on verifie sa coherence.\n\nChaque annee : Interets = Capital debut \xd7 i ; Amortissement = Annuite - Interets ;\nCapital fin = Capital debut - Amortissement (qui devient le Capital debut de l'annee suivante).\n\n**Travail demande :**\n1. Completer la boucle (interets, amortissement, mise a jour du capital).\n2. Recuperer le **capital restant en fin d'annee 5** \u2192 \`capital_fin5\` (doit retomber a ~0).\n3. Calculer le **total des interets** payes sur 5 ans \u2192 \`total_interets\`.\n""",\n        "starter": """emprunt = 200_000_000\ni = 0.095\nn = 5\nannuite = emprunt * i / (1 - (1 + i) ** -n)\n\ncapital = emprunt\ntotal_interets = 0.0\nfor annee in range(1, n + 1):\n    interets = ...                  # interets de l'annee\n    amortissement = annuite - interets\n    total_interets = total_interets + interets\n    capital = capital - amortissement   # capital restant du\n\ncapital_fin5 = capital\n\nprint("capital fin annee 5 =", round(capital_fin5, 2))\nprint("total interets      =", round(total_interets))\n""",\n        "solution": """\nemprunt = 200_000_000\ni = 0.095\nn = 5\nannuite = emprunt * i / (1 - (1 + i) ** -n)\ncapital = emprunt\ntotal_interets = 0.0\nfor annee in range(1, n + 1):\n    interets = capital * i\n    amortissement = annuite - interets\n    total_interets = total_interets + interets\n    capital = capital - amortissement\ncapital_fin5 = capital\n""",\n        "verifs": [\n            {"var": "capital_fin5", "tol": 500_000, "unite": "FCFA"},\n            {"var": "total_interets", "tol": 500_000, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_screening_dossiers",\n        "seance": 7,\n        "niveau": "avance",\n        "titre": "A4 \xb7 Comite de credit \u2014 trier 3 dossiers par DSCR",\n        "consigne": """\n### Decision sur un portefeuille de dossiers : le DSCR comme filtre\n\nTrois dossiers de credit arrivent en comite. Le seuil banquier d'acceptation est\n**DSCR >= 1,25**.\n\n| Dossier | CAF | Annuite |\n|---------|-----|---------|\n| AGRO-CI SARL | 155 M | 95 M |\n| BTP Kouassi & Associes | 120 M | 110 M |\n| Distribution Traore SA | 75 M | 52 M |\n\n**Travail demande :** parcourir les dossiers, calculer le DSCR de chacun, puis :\n1. compter combien sont **acceptables** (DSCR >= 1,25) \u2192 \`nb_acceptables\`\n2. retenir le **DSCR le plus faible** du portefeuille \u2192 \`dscr_min\`\n\nRappel : DSCR = CAF / Annuite.\n""",\n        "starter": """dossiers = [\n    {"nom": "AGRO-CI SARL", "caf": 155, "annuite": 95},\n    {"nom": "BTP Kouassi & Associes", "caf": 120, "annuite": 110},\n    {"nom": "Distribution Traore SA", "caf": 75, "annuite": 52},\n]\n\nnb_acceptables = 0\ndscr_min = 999.0\nfor d in dossiers:\n    dscr = ...                       # CAF / annuite\n    if dscr >= 1.25:\n        nb_acceptables = nb_acceptables + 1\n    if dscr < dscr_min:\n        dscr_min = ...\n\nprint("dossiers acceptables =", nb_acceptables)\nprint("DSCR le plus faible  =", round(dscr_min, 2))\n""",\n        "solution": """\ndossiers = [\n    {"nom": "AGRO-CI SARL", "caf": 155, "annuite": 95},\n    {"nom": "BTP Kouassi & Associes", "caf": 120, "annuite": 110},\n    {"nom": "Distribution Traore SA", "caf": 75, "annuite": 52},\n]\nnb_acceptables = 0\ndscr_min = 999.0\nfor d in dossiers:\n    dscr = d["caf"] / d["annuite"]\n    if dscr >= 1.25:\n        nb_acceptables = nb_acceptables + 1\n    if dscr < dscr_min:\n        dscr_min = dscr\n""",\n        "verifs": [\n            {"var": "nb_acceptables", "tol": 0.5, "unite": ""},\n            {"var": "dscr_min", "tol": 0.001, "unite": ""},\n        ],\n    },\n]\n\n\ndef exercice_par_id(eid):\n    for ex in EXERCICES:\n        if ex["id"] == eid:\n            return ex\n    return None\n\n\n# === app.py ===\n# -*- coding: utf-8 -*-\n"""App Panel \u2014 Exercices Python interactifs\nInitiation au metier de charge d'affaire / analyse credit bancaire (B3-AFE n\xb015)\nTgMaster University (prononcer "Tiji Master University").\n\nL'etudiant ecrit son code dans l'editeur, clique "Verifier", et l'app :\n  1. execute le code (sortie texte capturee),\n  2. compare la VALEUR des variables attendues a la solution de reference,\n     avec une tolerance numerique (robuste : pas de comparaison de chaines).\n\nLancement local :\n    pip install panel\n    panel serve app.py --show\n\nDeploiement (voir README.md) :\n    - Hugging Face Spaces (Docker) ou Railway  -> mode serveur\n    - panel convert app.py --to pyodide-worker  -> HTML statique (zero serveur),\n      a embarquer dans Moodle via une iframe.\n"""\nimport io\nimport contextlib\nimport math\nimport pathlib\nimport statistics\n\nimport panel as pn\n\n\n# --- Habillage "Indigo clair" (custom_panel.css place a cote de ce fichier) ---\n# CSS inline (compatible Pyodide, aucune lecture de fichier au runtime)\n_RAW_CSS = [r'''\n/* ===========================================================================\n   custom_panel.css \u2014 Habillage "Indigo clair" pour l'app Panel (app.py)\n   \xc0 placer \xe0 c\xf4t\xe9 de app.py. Charg\xe9 automatiquement par app.py (voir ce fichier).\n   Pour changer de direction visuelle : modifier les 6 variables de :root.\n   =========================================================================== */\n@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');\n\n:root {\n  --accent:        #3b46a0;\n  --accent-strong: #2b3576;\n  --accent-soft:   #eef0fb;\n  --page-bg:       #f1f3f9;\n  --surface:       #ffffff;\n  --surface-2:     #f7f8fc;\n  --border:        #e4e7f0;\n  --border-strong: #d2d7e4;\n  --text:          #1b2030;\n  --text-muted:    #687087;\n  --success:       #1b8a52;\n  --danger:        #c0492f;\n  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;\n  --font-mono: 'JetBrains Mono', ui-monospace, Menlo, Consolas, monospace;\n}\n\nbody, .bk-root {\n  font-family: var(--font-sans) !important;\n  color: var(--text);\n  background: var(--page-bg) !important;\n}\n.bk-root .bk-Column { background: transparent; }\n\n/* S\xe9lecteur d'exercice */\nselect.bk-input, .bk-input {\n  font-family: var(--font-sans) !important;\n  border: 1px solid var(--border-strong) !important;\n  border-radius: 8px !important;\n  color: var(--text) !important;\n  background: var(--surface) !important;\n  font-weight: 600;\n  padding: 9px 12px !important;\n}\nselect.bk-input:focus, .bk-input:focus {\n  outline: none !important;\n  border-color: var(--accent) !important;\n  box-shadow: 0 0 0 3px rgba(59,70,160,0.16) !important;\n}\n.bk-input-group label, label.bk {\n  font-weight: 600 !important;\n  color: var(--text-muted) !important;\n  font-size: 12px !important;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n/* Boutons */\n.bk-btn {\n  font-family: var(--font-sans) !important;\n  font-weight: 600 !important;\n  border-radius: 8px !important;\n  padding: 9px 16px !important;\n  border: 1px solid transparent !important;\n  transition: background .15s ease, color .15s ease;\n}\n.bk-btn-primary { background: var(--accent) !important; border-color: var(--accent) !important; color: #fff !important; }\n.bk-btn-primary:hover { background: var(--accent-strong) !important; }\n.bk-btn-default { background: var(--surface) !important; color: var(--text-muted) !important; border-color: var(--border-strong) !important; }\n.bk-btn-default:hover { background: var(--surface-2) !important; color: var(--text) !important; }\n.bk-btn-warning { background: transparent !important; color: var(--accent-strong) !important; border-color: var(--border-strong) !important; }\n.bk-btn-warning:hover { background: var(--accent-soft) !important; }\n.bk-btn-warning.bk-active { background: var(--accent-soft) !important; border-color: var(--accent) !important; }\n\n/* \xc9diteur de code (Ace) */\n.bk-root .ace_editor {\n  border: 1px solid var(--border) !important;\n  border-radius: 12px !important;\n  font-family: var(--font-mono) !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,0.06);\n  overflow: hidden;\n}\n\n/* \xc9nonc\xe9 + feedback (panes Markdown) \u2014 plats, sans carte (les cartes sont g\xe9r\xe9es par .main-panel) */\n.bk-root .markdown { line-height: 1.55; }\n.bk-root .markdown h3 { color: var(--text); font-weight: 800; }\n.bk-root .markdown code {\n  font-family: var(--font-mono) !important;\n  background: var(--accent-soft);\n  color: var(--accent-strong);\n  padding: 1.5px 6px; border-radius: 5px; font-size: 0.86em;\n}\n.bk-root .markdown table {\n  border-collapse: separate; border-spacing: 0;\n  border: 1px solid var(--border); border-radius: 10px; overflow: hidden;\n}\n.bk-root .markdown th {\n  background: var(--surface-2); text-align: left;\n  padding: 9px 13px !important; border-bottom: 1px solid var(--border);\n}\n.bk-root .markdown td {\n  padding: 8px 13px !important; border-bottom: 1px solid var(--border);\n  font-variant-numeric: tabular-nums;\n}\n.bk-root .markdown tr:nth-child(even) td { background: var(--surface-2); }\n\n.bk-root hr { border: none; border-top: 1px solid var(--border); margin: 6px 0; }\n\n/* =========================================================================\n   LAYOUT MAQUETTE \u2014 header + progression / sidebar cartes / panneau + \xe9diteur\n   ========================================================================= */\n\n/* --- En-t\xeate gradient + barre de progression --- */\n.app-header {\n  background: linear-gradient(100deg, var(--accent-strong), var(--accent)) !important;\n  border-radius: 16px !important;\n  padding: 18px 26px !important;\n  box-shadow: 0 8px 24px rgba(20,26,50,.14);\n  align-items: center !important;\n}\n.hdr-sub {\n  color: rgba(255,255,255,.72); font-size: 11.5px; font-weight: 600;\n  letter-spacing: .06em; text-transform: uppercase;\n}\n.hdr-title {\n  color: #fff; font-size: 20px; font-weight: 800; letter-spacing: -.01em; margin-top: 3px;\n}\n.prog-wrap { text-align: right; min-width: 200px; }\n.prog-pill {\n  color: #fff; font-size: 13px; font-weight: 700; margin-bottom: 7px;\n}\n.prog-track {\n  width: 200px; height: 9px; border-radius: 99px;\n  background: rgba(255,255,255,.22); overflow: hidden; margin-left: auto;\n}\n.prog-fill {\n  height: 100%; border-radius: 99px; background: #fff;\n  transition: width .35s ease;\n}\n\n/* --- Sidebar \xab Parcours d'exercices \xbb --- */\n.sidebar {\n  background: var(--surface); border: 1px solid var(--border);\n  border-radius: 16px; padding: 16px 14px !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,.06);\n}\n.sb-title { font-size: 14px; font-weight: 800; color: var(--text); }\n.sb-sub { font-size: 11.5px; color: var(--text-muted); margin-top: 1px; margin-bottom: 6px; }\n.section-head {\n  font-size: 10.5px; font-weight: 700; color: var(--text-muted);\n  letter-spacing: .07em; text-transform: uppercase;\n  margin: 14px 6px 6px;\n}\n\n/* Carte exercice = Row [badge | bouton-label | statut] */\n.exo-card {\n  align-items: center !important;\n  flex-wrap: nowrap !important;\n  overflow: hidden !important;\n  border: 1px solid var(--border) !important;\n  border-radius: 11px !important;\n  margin-bottom: 7px !important;\n  padding: 4px 8px !important;\n  background: var(--surface) !important;\n  transition: border-color .15s ease, background .15s ease, box-shadow .15s ease;\n}\n.exo-card:hover { border-color: var(--border-strong) !important; background: var(--surface-2) !important; }\n.exo-card.actif {\n  border-color: var(--accent) !important;\n  background: var(--accent-soft) !important;\n  box-shadow: 0 0 0 3px rgba(59,70,160,.12) !important;\n}\n/* TOUS les enfants flex doivent pouvoir r\xe9tr\xe9cir sous la largeur de leur contenu */\n.exo-card > * { min-width: 0 !important; }\n/* Badge (gauche) et pastille (droite) : taille fixe, ne r\xe9tr\xe9cissent pas */\n.exo-card > *:first-child { flex: 0 0 auto !important; }\n.exo-card > *:last-child  { flex: 0 0 auto !important; }\n/* Le bouton-label au milieu : prend l'espace restant et r\xe9tr\xe9cit */\n.exo-card > *:nth-child(2) { flex: 1 1 auto !important; min-width: 0 !important; }\n\n.exo-badge-sb {\n  font-family: var(--font-mono) !important; font-size: 11px; font-weight: 700;\n  color: var(--accent-strong); background: var(--accent-soft);\n  border: 1px solid var(--border); border-radius: 7px;\n  padding: 4px 7px; min-width: 34px; text-align: center;\n}\n.exo-card.actif .exo-badge-sb { background: #fff; }\n/* Le bouton-label occupe l'espace, transparent et sans bordure, texte tronqu\xe9 proprement */\n.exo-card .bk-btn, .exo-card .bk-btn-default {\n  background: transparent !important; border: none !important; box-shadow: none !important;\n  text-align: left !important; color: var(--text) !important;\n  font-weight: 600 !important; font-size: 12.5px !important;\n  padding: 6px 4px !important; line-height: 1.35 !important;\n  min-width: 0 !important; width: 100% !important; max-width: 100% !important;\n  display: block !important;\n  white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important;\n}\n.exo-card .bk-btn:hover { background: transparent !important; color: var(--accent-strong) !important; }\n.exo-stat {\n  flex: 0 0 auto; width: 20px; height: 20px; border-radius: 99px;\n  border: 2px solid var(--border-strong);\n  display: flex; align-items: center; justify-content: center;\n  font-size: 12px; color: transparent;\n}\n.exo-card.ok .exo-stat {\n  border-color: var(--success); background: var(--success); color: #fff;\n}\n\n/* --- Panneau principal --- */\n.main-panel {\n  background: var(--surface); border: 1px solid var(--border);\n  border-radius: 16px; padding: 22px 26px !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,.06);\n}\n.exo-head { align-items: center !important; }\n.exo-badge {\n  font-family: var(--font-mono) !important; font-weight: 800; font-size: 14px;\n  color: #fff; background: var(--accent); border-radius: 9px;\n  padding: 7px 11px; margin-right: 4px;\n}\n.exo-h-title { font-size: 18px; font-weight: 800; color: var(--text); }\n.tag-base, .tag-avance {\n  font-size: 10.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase;\n  padding: 4px 9px; border-radius: 99px;\n}\n.tag-base { color: var(--accent-strong); background: var(--accent-soft); }\n.tag-avance { color: #fff; background: linear-gradient(100deg, var(--accent-strong), var(--accent)); }\n\n/* --- Fen\xeatre \xe9diteur style macOS --- */\n.editor-window {\n  border: 1px solid var(--border-strong) !important;\n  border-radius: 12px !important; overflow: hidden;\n  box-shadow: 0 6px 18px rgba(20,26,50,.10);\n  background: #fbfbfd;\n}\n.editor-titlebar {\n  display: flex; align-items: center; gap: 9px;\n  background: var(--surface-2); border-bottom: 1px solid var(--border);\n  padding: 8px 13px;\n}\n.editor-titlebar .dot { width: 12px; height: 12px; border-radius: 99px; display: inline-block; }\n.dot-r { background: #ec6a5e; } .dot-y { background: #f4be4f; } .dot-g { background: #61c554; }\n.editor-titlebar .fname {\n  font-family: var(--font-mono) !important; font-size: 12px; color: var(--text-muted);\n  margin-left: 6px;\n}\n.editor-window .ace_editor { border: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n/* --- Carte feedback --- */\n.feedback-card {\n  background: var(--surface-2); border: 1px solid var(--border);\n  border-radius: 12px; padding: 6px 18px !important; margin-top: 4px !important;\n}\n\n/* --- Corps deux colonnes responsive --- */\n.body-row { align-items: flex-start !important; flex-wrap: wrap !important; gap: 16px; }\n.body-row > div { min-width: 0 !important; }\n.sidebar { flex: 0 0 280px !important; }\n.main-panel { flex: 1 1 420px !important; min-width: 0 !important; }\n/* Sur \xe9cran \xe9troit : la sidebar passe pleine largeur au-dessus du panneau */\n@media (max-width: 820px) {\n  .sidebar { flex-basis: 100% !important; }\n}\n\n''']\n\npn.extension("codeeditor", sizing_mode="stretch_width", raw_css=_RAW_CSS)\n\n# Palette de la maquette (Indigo clair)\nNAVY = "#2b3576"   # accent indigo (titres, messages neutres)\nRED = "#c0492f"    # erreurs\nGREEN = "#1b8a52"  # succes\n\n# Environnement d'execution autorise : modules surs pour du calcul financier.\nSAFE_MODULES = {"math": math, "statistics": statistics}\n\n\n# --------------------------------------------------------------------------- #\n# Moteur d'execution et de verification\n# --------------------------------------------------------------------------- #\ndef executer_code(code):\n    """Execute \`code\` dans un espace de noms neuf.\n    Retourne (namespace, sortie_texte, erreur_ou_None).\n    Pas de subprocess -> compatible Pyodide (WASM, execution dans le navigateur).\n    """\n    ns = dict(SAFE_MODULES)\n    sortie = io.StringIO()\n    erreur = None\n    try:\n        with contextlib.redirect_stdout(sortie):\n            exec(code, ns)  # noqa: S102 - outil pedagogique, execution voulue\n    except Exception as exc:  # noqa: BLE001\n        erreur = f"{type(exc).__name__} : {exc}"\n    return ns, sortie.getvalue(), erreur\n\n\n# Valeurs de reference : calculees UNE fois depuis la solution de chaque exercice.\ndef _valeurs_attendues(ex):\n    ns, _, err = executer_code(ex["solution"])\n    if err:\n        raise RuntimeError(f"Solution invalide pour {ex['id']} : {err}")\n    return {v["var"]: ns[v["var"]] for v in ex["verifs"]}\n\n\nATTENDU = {ex["id"]: _valeurs_attendues(ex) for ex in EXERCICES}\n\n\ndef verifier(ex, code):\n    """Renvoie (ok_global, markdown_feedback)."""\n    # Garde-fou pedagogique : tant qu'il reste des "..." (placeholders a completer),\n    # on ne lance pas le code -> on evite un TypeError cryptique sur Ellipsis.\n    lignes_a_completer = [i for i, ligne in enumerate(code.splitlines(), start=1)\n                          if "..." in ligne]\n    if lignes_a_completer:\n        nums = ", ".join(str(n) for n in lignes_a_completer)\n        return False, (f"<span style='color:{NAVY}'>\u270f\ufe0f Il reste des \`...\` \xe0 "\n                       f"compl\xe9ter (ligne(s) {nums}). Remplace chaque \`...\` par "\n                       f"ta formule, puis clique de nouveau sur "\n                       f"<b>V\xe9rifier</b>.</span>")\n\n    ns, sortie, erreur = executer_code(code)\n\n    lignes = []\n    if sortie.strip():\n        lignes.append("**Sortie de ton code :**")\n        lignes.append("\`\`\`\\n" + sortie.rstrip() + "\\n\`\`\`")\n\n    if erreur:\n        lignes.append(f"<span style='color:{RED}'>\u274c **Erreur d'ex\xe9cution :** "\n                      f"{erreur}</span>")\n        return False, "\\n\\n".join(lignes)\n\n    attendu = ATTENDU[ex["id"]]\n    tous_ok = True\n    details = []\n    for v in ex["verifs"]:\n        nom = v["var"]\n        unite = (" " + v["unite"]) if v["unite"] else ""\n        if nom not in ns or ns[nom] is Ellipsis:\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` n'est pas "\n                           f"encore calcul\xe9 (il vaut \`...\`).</span>")\n            continue\n        try:\n            val = float(ns[nom])\n        except (TypeError, ValueError):\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` doit \xeatre un "\n                           f"nombre.</span>")\n            continue\n        ref = float(attendu[nom])\n        if abs(val - ref) <= v["tol"]:\n            details.append(f"<span style='color:{GREEN}'>\u2705 \`{nom}\` = "\n                           f"{_fmt(val)}{unite}</span>")\n        else:\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` = {_fmt(val)}"\n                           f"{unite} \u2014 ce n'est pas la valeur attendue.</span>")\n\n    lignes.append("\\n".join(details))\n    if tous_ok:\n        lignes.append(f"<h3 style='color:{GREEN}'>\U0001f389 Exercice r\xe9ussi \u2014 "\n                      f"bravo !</h3>")\n    else:\n        lignes.append(f"<span style='color:{NAVY}'>V\xe9rifie tes formules et "\n                      f"r\xe9essaie.</span>")\n    return tous_ok, "\\n\\n".join(lignes)\n\n\ndef _fmt(x):\n    """Affichage lisible : entier si rond, sinon 4 decimales max."""\n    if abs(x - round(x)) < 1e-9:\n        return f"{int(round(x))}"\n    return f"{x:.4f}".rstrip("0").rstrip(".")\n\n\n# --------------------------------------------------------------------------- #\n# Interface \u2014 maquette : en-tete + progression / sidebar cartes / panneau editeur\n# --------------------------------------------------------------------------- #\nimport html as _html\n\nTOTAL = len(EXERCICES)\nsolved = set()                       # ids des exercices reussis\netat = {"id": EXERCICES[0]["id"]}     # exercice courant\n\n\ndef _split_titre(titre):\n    """'A1 \xb7 Obligation \u2014 trouver le YTM' -> ('A1', 'Obligation \u2014 trouver le YTM').\n    'Exercice 1 \xb7 ...' garde le badge tel quel ; sinon numerote."""\n    if "\xb7" in titre:\n        badge, label = titre.split("\xb7", 1)\n        return badge.strip(), label.strip()\n    return "", titre.strip()\n\n\n# --- Widgets de contenu ----------------------------------------------------- #\nconsigne = pn.pane.Markdown(sizing_mode="stretch_width")\nediteur = pn.widgets.CodeEditor(language="python", theme="tomorrow",\n                                height=360, sizing_mode="stretch_width")\nbouton = pn.widgets.Button(name="\u25b6 V\xe9rifier", button_type="primary", width=150)\nbouton_reset = pn.widgets.Button(name="\u21ba R\xe9initialiser", button_type="default",\n                                 width=150)\nbouton_sol = pn.widgets.Toggle(name="\U0001f441 Voir la solution", button_type="warning",\n                               width=160)\nfeedback = pn.pane.Markdown(sizing_mode="stretch_width")\n\nexo_head = pn.pane.HTML(sizing_mode="stretch_width")\ntitlebar = pn.pane.HTML(sizing_mode="stretch_width")\nprogress = pn.pane.HTML()\n\n\ndef _titlebar_html(eid):\n    n = next((i for i, e in enumerate(EXERCICES, 1) if e["id"] == eid), 1)\n    return ("<div class='editor-titlebar'>"\n            "<span class='dot dot-r'></span><span class='dot dot-y'></span>"\n            "<span class='dot dot-g'></span>"\n            f"<span class='fname'>exercice_{n:02d}.py</span></div>")\n\n\ndef _exo_head_html(ex):\n    badge, label = _split_titre(ex["titre"])\n    avance = ex.get("niveau") == "avance"\n    tag = ("<span class='tag-avance'>Avanc\xe9 \u2605\u2605\u2605</span>" if avance\n           else "<span class='tag-base'>Base \u2605</span>")\n    badge_html = (f"<span class='exo-badge'>{_html.escape(badge)}</span>"\n                  if badge else "")\n    return ("<div class='exo-head' style='display:flex;align-items:center;gap:12px'>"\n            f"{badge_html}"\n            f"<span class='exo-h-title'>{_html.escape(label)}</span>"\n            f"<span style='flex:1 1 auto'></span>{tag}</div>")\n\n\ndef maj_progress():\n    pct = round(100 * len(solved) / TOTAL)\n    progress.object = (\n        "<div class='prog-wrap'>"\n        f"<div class='prog-pill'>{len(solved)} / {TOTAL} r\xe9ussis</div>"\n        f"<div class='prog-track'><div class='prog-fill' style='width:{pct}%'></div></div>"\n        "</div>")\n\n\n# --- Cartes de la sidebar --------------------------------------------------- #\n# Une carte = Row[badge | bouton-label | pastille statut], css togglee a l'execution.\n# Bokeh 3.x rend chaque widget dans son propre shadow root : le CSS global\n# (.exo-card .bk-btn) ne traverse PAS ces frontieres. On injecte donc le style\n# directement dans le shadow root de chaque composant via stylesheets=[...].\ncartes = {}     # eid -> pn.Row\n_boutons_sb = {}\n_stats_sb = {}  # eid -> pn.pane.HTML (pastille statut)\n\n# Pastilles statut : styles INLINE (le selecteur .exo-card.ok .exo-stat ne traverse\n# pas le shadow root du pane HTML \u2014 on change donc directement le contenu du pane).\n_STAT_BASE = ("width:20px;height:20px;border-radius:99px;"\n              "border:2px solid #d2d7e4;display:flex;align-items:center;"\n              "justify-content:center;font-size:12px;color:transparent")\n_STAT_OK = ("width:20px;height:20px;border-radius:99px;"\n            "border:2px solid #1b8a52;background:#1b8a52;color:#fff;"\n            "display:flex;align-items:center;justify-content:center;font-size:12px")\n_STAT_VIDE = f"<div style='{_STAT_BASE}'>\u2713</div>"\n_STAT_PLEIN = f"<div style='{_STAT_OK}'>\u2713</div>"\n\n# Style injecte dans le shadow root de la Row (carte) : fixe les flex des enfants.\nROW_SHEET = """\n:host { align-items: center; }\n.bk-panel-models-markup-HTML { flex: 0 0 auto !important; }\n.bk-panel-models-widgets-Button { flex: 1 1 auto !important; min-width: 0 !important; }\n"""\n\n# Style injecte dans le shadow root du Button-label : transparent, titre sur 2 lignes (lisible).\nBTN_SHEET = """\n:host { width: 100%; min-width: 0; }\n.bk-btn, .bk-btn-default {\n  background: transparent !important; border: none !important; box-shadow: none !important;\n  color: #1b2030 !important; text-align: left !important;\n  font-weight: 600 !important; font-size: 12.5px !important;\n  padding: 6px 4px !important; line-height: 1.3 !important;\n  display: block !important; width: 100% !important; max-width: 100% !important;\n  min-width: 0 !important;\n  white-space: normal !important; overflow-wrap: break-word !important; word-break: normal !important;\n}\n.bk-btn:hover, .bk-btn-default:hover { background: transparent !important; color: #2b3576 !important; }\n"""\n\n\ndef _make_carte(ex):\n    badge, label = _split_titre(ex["titre"])\n    b = pn.widgets.Button(name=label, button_type="default", sizing_mode="stretch_width",\n                          stylesheets=[BTN_SHEET])\n    b.on_click(lambda evt, eid=ex["id"]: select(eid))\n    _boutons_sb[ex["id"]] = b\n    stat = pn.pane.HTML(_STAT_VIDE, width=26)\n    _stats_sb[ex["id"]] = stat\n    badge_pane = pn.pane.HTML(f"<div class='exo-badge-sb'>{_html.escape(badge or '\u2022')}</div>",\n                              width=46)\n    row = pn.Row(badge_pane, b, stat, css_classes=["exo-card"],\n                 stylesheets=[ROW_SHEET], sizing_mode="stretch_width")\n    cartes[ex["id"]] = row\n    return row\n\n\ndef _maj_cartes():\n    for eid, row in cartes.items():\n        cls = ["exo-card"]\n        if eid in solved:\n            cls.append("ok")\n        if eid == etat["id"]:\n            cls.append("actif")\n        row.css_classes = cls\n        _stats_sb[eid].object = _STAT_PLEIN if eid in solved else _STAT_VIDE\n\n\n# --- Selection / verification ---------------------------------------------- #\ndef select(eid):\n    etat["id"] = eid\n    ex = exercice_par_id(eid)\n    exo_head.object = _exo_head_html(ex)\n    consigne.object = ex["consigne"]\n    editeur.value = ex["starter"]\n    titlebar.object = _titlebar_html(eid)\n    feedback.object = ""\n    bouton_sol.value = False\n    _maj_cartes()\n\n\ndef on_verifier(event):\n    eid = etat["id"]\n    ex = exercice_par_id(eid)\n    ok, md = verifier(ex, editeur.value)\n    feedback.object = md\n    if ok and eid not in solved:\n        solved.add(eid)\n        _maj_cartes()\n        maj_progress()\n\n\ndef on_reset(event):\n    ex = exercice_par_id(etat["id"])\n    editeur.value = ex["starter"]\n    feedback.object = ""\n    bouton_sol.value = False\n\n\ndef on_solution(event):\n    ex = exercice_par_id(etat["id"])\n    editeur.value = ex["solution"].strip() if bouton_sol.value else ex["starter"]\n\n\nbouton.on_click(on_verifier)\nbouton_reset.on_click(on_reset)\nbouton_sol.param.watch(on_solution, "value")\n\n\n# --- Assemblage de la sidebar ---------------------------------------------- #\nsidebar_items = [\n    pn.pane.HTML("<div class='sb-title'>Parcours d'exercices</div>"\n                 "<div class='sb-sub'>Charg\xe9 d'affaires &amp; analyse cr\xe9dit</div>"),\n]\n_base = [e for e in EXERCICES if e.get("niveau") != "avance"]\n_avance = [e for e in EXERCICES if e.get("niveau") == "avance"]\nif _base:\n    sidebar_items.append(pn.pane.HTML("<div class='section-head'>Exercices de base \u2605</div>"))\n    sidebar_items += [_make_carte(e) for e in _base]\nif _avance:\n    sidebar_items.append(pn.pane.HTML("<div class='section-head'>Exercices avanc\xe9s \u2605\u2605\u2605</div>"))\n    sidebar_items += [_make_carte(e) for e in _avance]\n\nsidebar = pn.Column(*sidebar_items, css_classes=["sidebar"],\n                    sizing_mode="stretch_width")\n\n# --- En-tete ---------------------------------------------------------------- #\nheader = pn.Row(\n    pn.pane.HTML(\n        "<div class='hdr-sub'>TgMaster University \xb7 B3 \u2014 AFE</div>"\n        "<div class='hdr-title'>Exercices Python \u2014 Charg\xe9 d'affaires &amp; analyse cr\xe9dit</div>"),\n    pn.HSpacer(),\n    progress,\n    css_classes=["app-header"], sizing_mode="stretch_width",\n)\n\n# --- Panneau principal ------------------------------------------------------ #\neditor_win = pn.Column(titlebar, editeur, css_classes=["editor-window"],\n                       sizing_mode="stretch_width")\nmain = pn.Column(\n    exo_head,\n    consigne,\n    editor_win,\n    pn.Row(bouton, bouton_reset, bouton_sol),\n    pn.pane.HTML("<div style='font-weight:700;color:#2b3576;margin-top:4px'>R\xe9sultat</div>"),\n    pn.Column(feedback, css_classes=["feedback-card"], sizing_mode="stretch_width"),\n    css_classes=["main-panel"], sizing_mode="stretch_width",\n)\n\nbody = pn.Row(sidebar, main, css_classes=["body-row"],\n              sizing_mode="stretch_width")\napp = pn.Column(header, body, sizing_mode="stretch_width", max_width=1240)\n\n# Etat initial\nmaj_progress()\nselect(etat["id"])\n\napp.servable(title="Exercices Python \u2014 AFE 15")\n\n\nawait write_doc()
  `

  try {
    const [docs_json, render_items, root_ids] = await self.pyodide.runPythonAsync(code)
    self.postMessage({
      type: 'render',
      docs_json: docs_json,
      render_items: render_items,
      root_ids: root_ids
    })
  } catch(e) {
    const traceback = `${e}`
    const tblines = traceback.split('\n')
    self.postMessage({
      type: 'status',
      msg: tblines[tblines.length-2]
    });
    throw e
  }
}

self.onmessage = async (event) => {
  const msg = event.data
  if (msg.type === 'rendered') {
    self.pyodide.runPythonAsync(`
    from panel.io.state import state
    from panel.io.pyodide import _link_docs_worker

    _link_docs_worker(state.curdoc, sendPatch, setter='js')
    `)
  } else if (msg.type === 'patch') {
    self.pyodide.globals.set('patch', msg.patch)
    self.pyodide.runPythonAsync(`
    from panel.io.pyodide import _convert_json_patch
    state.curdoc.apply_json_patch(_convert_json_patch(patch), setter='js')
    `)
    self.postMessage({type: 'idle'})
  } else if (msg.type === 'location') {
    self.pyodide.globals.set('location', msg.location)
    self.pyodide.runPythonAsync(`
    import json
    from panel.io.state import state
    from panel.util import edit_readonly
    if state.location:
        loc_data = json.loads(location)
        with edit_readonly(state.location):
            state.location.param.update({
                k: v for k, v in loc_data.items() if k in state.location.param
            })
    `)
  }
}

startApplication()